// All departments list in order (12 departments)
export const ALL_DEPARTMENTS = [
  auditForms["FG"],
  auditForms["MNTC"],
  auditForms["STR"],
  auditForms["HRD"],
  auditForms["QA"],
  auditForms["PROD"],
  auditForms["PUR"],
  auditForms["QMS"],
  auditForms["TM"],
  auditForms["MKT"],
  auditForms["TRM"],
  auditForms["NPD"]
];

// Helper function to get department by ID
export const getDepartmentById = (id) => {
  return ALL_DEPARTMENTS.find(dept => dept.id === id);
};

// Helper function to get department by sheet key
export const getDepartmentBySheetKey = (sheetKey) => {
  return ALL_DEPARTMENTS.find(dept => dept.sheetKey === sheetKey);
};



